<script setup>
import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { ArrowLeft, LocateFixed } from 'lucide-vue-next'
import { useRoute, useRouter } from 'vue-router'
import { getAddress } from '../services/orderService'
import { reverseGeocode } from '../services/geocodingService'
import { useSessionStore } from '../stores/session'
import L from 'leaflet'; import 'leaflet/dist/leaflet.css'
const router = useRouter(); const route = useRoute(); const session = useSessionStore(); const mapElement = ref(null); const address = ref(null); const loading = ref(false); const gpsError = ref(''); const geocoding = ref(false); let map; let marker; let requestId = 0
const point = ref({ lat: 13.6929, lon: -89.2182 })
function updatePoint(lat, lon, shouldGeocode = true) { point.value = { lat: Number(lat), lon: Number(lon) }; marker?.setLatLng([point.value.lat, point.value.lon]); if (shouldGeocode) lookup() }
async function lookup() { const id = ++requestId; geocoding.value = true; try { const result = await reverseGeocode(point.value.lat, point.value.lon); if (id === requestId) address.value = result } catch { if (id === requestId) address.value = null } finally { if (id === requestId) geocoding.value = false } }
function useGps() { if (!navigator.geolocation) { gpsError.value = 'Tu navegador no permite obtener la ubicación.'; return }; loading.value = true; gpsError.value = ''; navigator.geolocation.getCurrentPosition(({ coords }) => { map.setView([coords.latitude, coords.longitude], 17); updatePoint(coords.latitude, coords.longitude); loading.value = false }, (error) => { loading.value = false; gpsError.value = error.code === 1 ? 'Permiso denegado. Puedes elegir el punto manualmente en el mapa.' : 'No pudimos obtener tu ubicación. Puedes elegirla manualmente.' }, { enableHighAccuracy: true, timeout: 10000, maximumAge: 60000 }) }
function confirm() { const from = route.query.from || 'checkout'; const redirect = typeof route.query.redirect === 'string' ? route.query.redirect : ''; sessionStorage.setItem('pedidosya-address-draft', JSON.stringify({ id: route.params.id || null, ...point.value, geocode: address.value, from, redirect })); router.push({ name: 'address-details', query: { from, ...(redirect ? { redirect } : {}) } }) }
onMounted(async () => { if (route.params.id) { const existing = await getAddress(route.params.id, session.user.id); if (existing?.latitud && existing?.longitud) { point.value = { lat: Number(existing.latitud), lon: Number(existing.longitud) }; address.value = { detalle: existing.detalle, display: existing.detalle }; } } await nextTick(); map = L.map(mapElement.value, { zoomControl: false }).setView([point.value.lat, point.value.lon], route.params.id ? 17 : 13); L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { attribution: '&copy; OpenStreetMap contributors' }).addTo(map); L.control.zoom({ position: 'bottomright' }).addTo(map); marker = L.marker([point.value.lat, point.value.lon]).addTo(map); map.on('moveend', () => { const center = map.getCenter(); updatePoint(center.lat, center.lng) }); lookup(); if (route.query.gps === '1') useGps() })
onBeforeUnmount(() => map?.remove())
</script>
<template><main class="address-map-page"><button class="address-map-back" @click="router.back"><ArrowLeft :size="22" /></button><div ref="mapElement" class="address-map" /><button class="address-map-gps" :disabled="loading" @click="useGps"><LocateFixed :size="20" /> {{ loading ? 'Buscando…' : 'Usar mi ubicación actual' }}</button><section class="address-map-sheet"><div class="location-picker__handle" /><h1>Selecciona tu punto de entrega</h1><p v-if="geocoding">Buscando dirección…</p><p v-else-if="address?.display">{{ address.display }}</p><p v-else>No pudimos identificar la dirección. Puedes completar los detalles manualmente.</p><small>Atribución: OpenStreetMap / Nominatim</small><p v-if="gpsError" class="address-map-error">{{ gpsError }}</p><button class="address-map-confirm" @click="confirm">Confirmar ubicación</button></section></main></template>
